  for (const p of D.papers) counts.set(p.ax.A1_paradigm, (counts.get(p.ax.A1_paradigm) || 0) + 1);
  const big = [...counts.entries()].filter(([, n]) => n >= LANE_MIN).sort((a, b) => b[1] - a[1]).map(([v]) => v);
  const lanes = big.map(v => ({ key: v, name: pretty(v), papers: [] })), other = { key: "__other", name: "Other paradigms", papers: [] };
  for (const p of D.papers) (lanes.find(l => l.key === p.ax.A1_paradigm) || other).papers.push(p);
  if (other.papers.length) lanes.push(other);
